		}

		yaml, err := repoCtrl.PipelineGenerate(ctx, session, repoRef)
		if err != nil {
			render.TranslatedUserError(ctx, w, err)
			return
		}

		w.Header().Set("Content-Type", "text/yaml; charset=utf-8")
		w.WriteHeader(http.StatusOK)
		_, _ = w.Write(yaml)
	}
}

